function draw(ctx, state, t) {
  var top = 36;
  var bot = 286;
  var left = 48;
  var right = 560;
  var w = state.w;
  var h = state.h;
  var base = state.base;
  var pos = state.pos;
  var i = state.dim;
  var d = state.d;
  var thr = 0;
  function fmt(v) { return Math.round(v * 100) / 100; }
  var mid = (top + bot) / 2;
  var amp = (bot - top) / 2 - 10;
  var e = (2 * i) / d;
  var den = Math.pow(base, e);
  var N = 60;
  var pmax = 120;
  var k = 0;
  var p = 0;
  var arg = 0;
  var v = 0;
  var x = 0;
  var y = 0;
  var ythr = mid - thr * amp;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(left, ythr);
  ctx.lineTo(right, ythr);
  ctx.stroke();
  ctx.strokeStyle = "#1f4b99";
  ctx.lineWidth = 2;
  ctx.beginPath();
  for (k = 0; k <= N; k++) {
    p = (k / N) * pmax;
    arg = p / den;
    v = Math.sin(arg);
    x = left + (p / pmax) * (right - left);
    y = mid - v * amp;
    if (k === 0) { ctx.moveTo(x, y); } else { ctx.lineTo(x, y); };
  };
  ctx.stroke();
  arg = pos / den;
  v = Math.sin(arg);
  x = left + (pos / pmax) * (right - left);
  y = mid - v * amp;
  ctx.fillStyle = "#c4512c";
  ctx.beginPath();
  ctx.arc(x, y, 6, 0, Math.PI * 2);
  ctx.fill();
  ctx.strokeStyle = "#c4512c";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(x, top);
  ctx.lineTo(x, bot);
  ctx.stroke();
  ctx.fillStyle = "#1f4b99";
  ctx.font = "12px sans-serif";
  ctx.fillText("threshold " + fmt(thr), 48, ythr - 8);
  ctx.fillText("pos = " + fmt(pos) + " val = " + fmt(v), 48, 318);
  ctx.fillText("toy arXiv 1706.03762", 48, 344);
}
